/* A generator is a thing that declines to emit. Say what it refuses
   before you say what it makes. */
const RULES = [
  ['has an id',     (x) => typeof x.id === 'string' && x.id.length > 0],
  ['does not gate', (x) => !('milestones' in x) && !('review' in x)],
];

function check(items) {
  const out = [], refused = [];
  for (const x of items) {
    const broke = RULES.filter(([, ok]) => !ok(x)).map(([name]) => name);
    if (broke.length) refused.push([x.id || '(unnamed)', broke]);
    else out.push(x);
  }
  return { out, refused };
}

/* the bad case, on purpose — a validator that is never shown one is a
   validator nobody has tested */
const { out, refused } = check([
  { id: 'the-observatory' },
  { id: 'the-farm', milestones: ['q1'] },
  { },
]);

console.log('kept   ', out.map((x) => x.id));
console.log('refused', refused);
refused.length;
